import{describe,it,expect}from"vitest";import{STYLES,PARTS_PALETTE}from"../../frontend/temple-architect/script.js";describe("Temple Architect Challenge Logic",()=>{it("should include Nagara, Dravidian, and Vesara styles dataset",()=>{expect(Array.isArray(STYLES)).toBe(!0),expect(STYLES.length).toBe(3);const e=STYLES.map(e=>e.id);expect(e).toContain("nagara"),expect(e).toContain("dravidian"),expect(e).toContain("vesara")}),it("should provide architectural components for top, middle, and base parts",()=>{expect(Array.isArray(PARTS_PALETTE)).toBe(!0),expect(PARTS_PALETTE.length).toBe(9);const e=PARTS_PALETTE.map(e=>e.type);expect(e).toContain("top"),expect(e).toContain("middle"),expect(e).toContain("base")})});